export function calculateRate(carrier: ShippingCarrier, destination: Address, weight: number): number {
  let baseRate: number = 5.99;
  let weightRate: number = (weight * 0.5);
  if ((destination.country !== 'US')) {
    baseRate = 25.99;
    weightRate = (weight * 1.5);
  }
  let carrierMultiplier: number = 1.0;
  if ((carrier === ShippingCarrier.FedEx)) {
    carrierMultiplier = 1.2;
  }
  if ((carrier === ShippingCarrier.Ups)) {
    carrierMultiplier = 1.1;
  }
  return ((baseRate + weightRate) * carrierMultiplier);
}

// Map external carrier event codes to internal status enum
export function mapFedExStatus(eventType: string): ShipmentStatus {
  return ShipmentStatus.equalsKeyword(eventType, ShipmentStatus.InTransit);
}

export function generateTrackingNumber(): string {
  return `TRACK-${format(new Date(), 'yyyyMMdd')}-${Array.from({ length: 10 }, () => 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'.charAt(Math.floor(Math.random() * 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'.length))).join('').toUpperCase()}`;
}
